(function(){var M={"共产主义者同盟成立": {"bg": "19 世纪 40 年代欧洲工人运动兴起，正义者同盟亟需科学理论指导。", "points": ["1847 年马克思、恩格斯加入并改组正义者同盟", "改名为「共产主义者同盟」", "以「全世界无产者，联合起来」为口号", "委托马恩起草党纲（即《共产党宣言》）"], "impact": "世界上第一个国际无产阶级政党，为马克思主义与工人运动结合奠定组织基础。"}, "哥达合并大会": {"bg": "德国工人运动分裂为爱森纳赫派与拉萨尔派，统一呼声高涨。", "points": ["1875 年 5 月两派在哥达合并", "成立德国社会主义工人党", "通过《哥达纲领》", "马克思作《哥达纲领批判》指出其原则性让步"], "impact": "德国工人运动实现统一，同时暴露了纲领问题上的分歧。"}, "马克思逝世": {"bg": "马克思晚年贫病交加，仍坚持理论研究。", "points": ["1883 年 3 月 14 日在伦敦逝世", "葬于海格特公墓", "恩格斯致悼词"], "impact": "国际工人运动失去最伟大的导师，其学说继续指引各国无产阶级。"}, "恩格斯逝世": {"bg": "恩格斯晚年整理马克思遗稿并指导国际工人运动。", "points": ["整理出版《资本论》第二、三卷", "1895 年 8 月 5 日在伦敦逝世", "遗嘱将其骨灰撒入大海"], "impact": "马克思主义经典体系基本完成，工人运动进入新的发展时期。"}, "俄国二月革命": {"bg": "一战使俄国危机深重，沙皇统治摇摇欲坠。", "points": ["1917 年 3 月（俄历二月）彼得格勒工人士兵起义", "推翻沙皇专制制度", "出现临时政府与苏维埃两个政权并存局面"], "impact": "为十月革命创造了条件。"}, "德国十一月革命": {"bg": "一战末期德国战败、饥荒与革命情绪高涨。", "points": ["1918 年 11 月基尔水兵起义", "革命席卷全国", "推翻德意志帝国", "卢森堡、李卜克内西领导左派斗争"], "impact": "结束帝制，但革命成果被社会民主党右派掌握。"}, "匈牙利苏维埃共和国成立": {"bg": "一战战败与十月革命影响下，匈牙利革命形势高涨。", "points": ["1919 年 3 月 21 日建立苏维埃共和国", "库恩·贝拉领导", "实行企业国有化等政策", "同年 8 月在内外夹击下失败"], "impact": "中欧地区首次尝试建立无产阶级专政政权。"}, "共产国际第二次代表大会": {"bg": "各国共产党相继建立，亟需统一组织原则。", "points": ["1920 年 7—8 月在彼得格勒开幕、莫斯科续会", "通过《加入共产国际的条件》（二十一条）", "通过《共产国际章程》"], "impact": "规范了各国党的组织建设，也强化了高度集中的领导体制。"}, "中共二大": {"bg": "中共成立后需要明确革命纲领。", "points": ["1922 年 7 月在上海召开", "第一次提出反帝反封建的民主革命纲领", "通过党的第一个党章"], "impact": "指明了中国革命的阶段与任务，是新民主主义革命理论的重要一步。"}, "列宁逝世": {"bg": "列宁晚年患病，党内就建设道路出现分歧。", "points": ["1924 年 1 月 21 日在哥尔克村逝世", "终年 54 岁", "斯大林等继续领导苏联"], "impact": "国际共运失去伟大领袖，苏联进入斯大林时期。"}, "秋收起义": {"bg": "大革命失败后，中共决定以武装斗争反抗国民党。", "points": ["1927 年 9 月毛泽东领导湘赣边界起义", "受挫后转向农村", "创建井冈山革命根据地"], "impact": "开辟了农村包围城市、武装夺取政权的道路。"}, "广州起义": {"bg": "继南昌起义、秋收起义后，中共在城市发动武装反抗。", "points": ["1927 年 12 月张太雷、叶挺等领导起义", "建立广州苏维埃政府", "因力量悬殊失败"], "impact": "是中共独立领导武装斗争的重要尝试。"}, "井冈山会师": {"bg": "秋收起义部队与南昌起义余部需要会合。", "points": ["1928 年 4 月朱德、毛泽东两部在宁冈砻市会师", "合编工农红军第四军", "朱德任军长、毛泽东任党代表"], "impact": "壮大了井冈山根据地力量，是人民军队建设的重要节点。"}, "中华苏维埃共和国成立": {"bg": "各根据地与红军发展壮大，需要统一政权。", "points": ["1931 年 11 月中华苏维埃第一次全国代表大会在瑞金召开", "定都瑞金", "毛泽东任主席", "通过宪法大纲、土地法等"], "impact": "建立了与国民党政权对峙的工农民主政权。"}, "遵义会议": {"bg": "第五次反「围剿」失败，红军被迫长征，党内亟需纠正错误军事路线。", "points": ["1935 年 1 月在遵义召开", "确立毛泽东在党和红军中的领导地位", "结束「左」倾教条主义在中央的统治"], "impact": "是党史上生死攸关的转折点。"}, "全面抗战爆发（七七事变）": {"bg": "日本发动全面侵华战争，民族危亡之际。", "points": ["1937 年 7 月 7 日卢沟桥事变", "中国全民族抗战开始", "中共推动建立抗日民族统一战线"], "impact": "中国革命进入抗日战争时期。"}, "抗日战争胜利": {"bg": "世界反法西斯战争进入最后阶段，中国战场全面反攻。", "points": ["1945 年 8 月日本宣布无条件投降", "9 月 9 日在南京举行中国战区受降仪式", "中国抗日战争取得胜利"], "impact": "近代以来中国反抗外来侵略的第一次完全胜利。"}, "斯大林逝世": {"bg": "战后苏联社会主义建设与冷战对峙中，斯大林去世。", "points": ["1953 年 3 月 5 日在莫斯科逝世", "苏联进入集体领导过渡期", "国际共运格局随之变动"], "impact": "对苏联与国际共运产生深远影响。"}, "三大改造与第一个五年计划": {"bg": "新中国成立后需要恢复经济并向社会主义过渡。", "points": ["对农业、手工业、资本主义工商业进行社会主义改造", "实施第一个五年计划", "1956 年基本完成三大改造", "奠定工业化初步基础"], "impact": "确立了社会主义基本制度，建立起独立的工业体系雏形。"}, "波匈事件": {"bg": "苏共二十大后东欧出现思想动荡与社会不满。", "points": ["1956 年 6 月波兰波兹南事件", "1956 年 10 月匈牙利事件", "苏军两次介入"], "impact": "暴露了苏联模式的矛盾，引发各国党对社会主义道路的反思。"}, "我国第一颗原子弹爆炸": {"bg": "面对核讹诈与封锁，中国决定自力更生发展核力量。", "points": ["1964 年 10 月 16 日在罗布泊试验成功", "中国成为第五个拥有核武器的国家", "打破大国的核垄断"], "impact": "极大提升了国防实力与国际地位。"}, "「东方红一号」卫星发射": {"bg": "在「两弹一星」工程推进下，中国着手发展航天事业。", "points": ["1970 年 4 月 24 日发射成功", "中国第一颗人造地球卫星", "播送《东方红》乐曲"], "impact": "中国进入航天时代，跻身航天国家之列。"}, "恢复中国在联合国合法席位": {"bg": "亚非拉民族解放运动高涨，国际格局发生变化。", "points": ["1971 年 10 月第 26 届联大通过 2758 号决议", "恢复新中国在联合国的合法席位", "驱逐台湾当局代表"], "impact": "是新中国外交的重大胜利。"}, "十一届三中全会": {"bg": "「文化大革命」结束后，国家面临拨乱反正与发展抉择。", "points": ["1978 年 12 月在北京召开", "确定把工作中心转向经济建设", "作出实行改革开放的决策"], "impact": "开启了改革开放和社会主义现代化建设新时期。"}};
 ((window.SITE_EXTRA&&window.SITE_EXTRA.events)||[]).forEach(function(e){var m=M[e.name];if(!m)return;if(m.bg)e.bg=m.bg;if(m.points)e.points=m.points;if(m.impact)e.impact=m.impact;});})();


/* ===== U7 增补：世界性重大事件（国际共运 / 民族解放 / 世界史，逐条联网核实）===== */
(function(){var N=[{"year": "1948", "name": "朝鲜民主主义人民共和国成立", "desc": "1948年9月9日，朝鲜民主主义人民共和国在平壤宣告成立，金日成出任内阁首相。此前同年8月15日半岛南部已成立大韩民国。南北分别建政，朝鲜半岛正式分裂为两个对立政权。"},{"year": "1950", "name": "朝鲜战争爆发", "desc": "1950年6月25日，朝鲜半岛三八线附近爆发大规模武装冲突，朝鲜人民军越过三八线向南进攻。联合国安理会通过决议介入，美国等组成「联合国军」参战。同年10月中国人民志愿军入朝，战事在三八线一带陷入胶着。"},{"year": "1945", "name": "越南八月革命", "desc": "1945年8月，印度支那共产党趁日本投降发动总起义。8月19日河内起义成功，顺化、西贡相继解放，末代皇帝保大退位。9月2日胡志明在河内巴亭广场宣读《独立宣言》，宣告越南民主共和国成立。", "people": ["胡志明"]},{"year": "1954", "name": "奠边府战役", "desc": "1954年3月13日至5月7日，越南人民军围攻越南西北的奠边府法军据点群，经约55昼夜激战全歼守军1.6万余人。此役迫使法国在《日内瓦协议》上签字，结束印度支那战争。", "people": ["胡志明"]},{"year": "1975", "name": "越南南方解放与统一", "desc": "1975年3月起，越南南方人民武装发动春季总进攻，接连取得西原、顺化—岘港等战役胜利。4月26日发起胡志明战役，4月30日攻占西贡，南越政权宣布投降。1976年越南南北统一，改国名为越南社会主义共和国。", "people": ["胡志明"]},{"year": "1965", "name": "印尼「九三〇事件」", "desc": "1965年9月30日夜，印尼总统卫队军官翁东等人在雅加达发动行动，绑架并杀害六名陆军将领。苏哈托随即指挥陆军平定，并指控印尼共产党为幕后主使，发动全国性反共清洗。苏加诺权威受损，苏哈托逐步掌权。"},{"year": "1959", "name": "古巴革命胜利", "desc": "1958年底，卡斯特罗领导的起义军发动反攻，攻占圣克拉拉等地。1959年1月1日，独裁者巴蒂斯塔逃亡国外，起义军进入哈瓦那并建立临时政府，古巴革命取得胜利，卡斯特罗随后出任政府总理。", "people": ["菲德尔·卡斯特罗", "切·格瓦拉"]},{"year": "1962", "name": "古巴导弹危机", "desc": "1962年10月，美国发现苏联在古巴部署中程核导弹，肯尼迪宣布对古巴实行海上封锁，美苏一度濒临核战争。经秘密谈判，苏联撤走导弹，美国承诺不入侵古巴并撤走部署在土耳其的导弹，危机得以化解。", "people": ["菲德尔·卡斯特罗"]},{"year": "1967", "name": "切·格瓦拉在玻利维亚遇害", "desc": "1967年10月8日，切·格瓦拉在玻利维亚尤罗峡谷战斗中被政府军俘获，押至拉伊格拉村。次日他在玻利维亚军方命令下被处决，遗体随后被秘密掩埋。1997年其遗骸在巴耶格兰德附近被找到并运回古巴。", "people": ["切·格瓦拉"]},{"year": "1940", "name": "托洛茨基在墨西哥遇刺", "desc": "1940年8月20日，流亡墨西哥的托洛茨基在墨西哥城郊科约阿坎的住所内，被以化名接近的苏联特工拉蒙·麦卡德用冰镐击伤头部，次日伤重身亡。凶手被墨西哥当局判刑。", "people": ["列夫·托洛茨基"]},{"year": "1968", "name": "布拉格之春与苏联入侵捷克斯洛伐克", "desc": "1968年初，捷共第一书记杜布切克推行「带有人性面孔的社会主义」改革，被称为「布拉格之春」。8月20日夜，苏联等华约五国出兵占领捷克斯洛伐克，改革被终止。"},{"year": "1980", "name": "波兰团结工会成立", "desc": "1980年7月波兰政府提高食品价格引发全国罢工。8月，格但斯克列宁造船厂工人罢工，瓦文萨领导厂际罢工委员会。9月，各地独立工会代表在格但斯克宣告成立「独立自治团结工会」，成为东欧首个非共产党控制的独立工会。"},{"year": "1970", "name": "智利阿连德当选总统", "desc": "1970年9月，智利左翼「人民团结」联盟候选人萨尔瓦多·阿连德在总统选举中以约36%的得票率居首；因未过半，选举交由国会裁决。在基督教民主党支持下，阿连德于10月获国会确认，11月就任总统。"},{"year": "1973", "name": "智利军事政变", "desc": "1973年9月11日，智利陆军司令皮诺切特联合海、空军和警察在圣地亚哥发动政变，要求总统阿连德辞职。军队围攻并轰炸总统府拉莫内达宫，阿连德身亡，人民团结政府被推翻。皮诺切特此后执政至1990年。"},{"year": "1968", "name": "法国五月风暴", "desc": "1968年5月，巴黎大学生因抗议教育体制和警察进入校园而大规模罢课示威，运动迅速蔓延全国。数百万工人随后罢工声援并占领工厂，法国一度陷入瘫痪。戴高乐政府解散议会并举行大选，运动于6月逐渐消退。"},{"year": "1989", "name": "柏林墙倒塌", "desc": "1989年11月9日晚，东德官员沙博夫斯基在记者会上误称新的旅行规定「立即生效」，宣布开放边界。大批东德市民随即涌向柏林墙各检查站，边防军未加阻拦，柏林墙事实上被打开，加速两德统一与冷战结束。"},{"year": "1960", "name": "非洲独立年", "desc": "1960年，非洲有17个国家获得独立，多数为法属殖民地，包括喀麦隆、塞内加尔、马里、尼日利亚等，这一年因而被称为「非洲独立年」。1957年加纳已率先独立，非洲民族解放运动由此进入高潮。"},{"year": "1954—1962", "name": "阿尔及利亚独立战争", "desc": "1954年11月，阿尔及利亚民族解放阵线在奥雷斯山区发动武装起义，反抗法国殖民统治。战争以游击战与城市斗争相结合，法国投入重兵并实施镇压。1962年双方签订《埃维昂协议》，阿尔及利亚宣告独立。"},{"year": "1952", "name": "埃及七月革命", "desc": "1952年7月23日，纳赛尔领导的「自由军官组织」在开罗发动起义，控制军队和首都。7月26日国王法鲁克一世退位流亡。次年废除君主制成立埃及共和国，纳吉布任总统，纳赛尔任总理。"},{"year": "1974", "name": "葡萄牙康乃馨革命", "desc": "1974年4月25日，葡萄牙中下级军官组成的「武装部队运动」在里斯本发动政变，推翻持续四十余年的萨拉查—卡埃塔诺独裁政权。军人以插在枪口的康乃馨为标志，政变未发生大规模流血，此后葡萄牙推行民主化和非殖民化。"},{"year": "1979", "name": "尼加拉瓜桑地诺革命", "desc": "1979年，桑地诺民族解放阵线在多年游击斗争基础上发动全国攻势。6月成立民族复兴临时政府，7月17日索摩查下台出逃，7月19日桑解阵部队进入首都马那瓜，索摩查家族四十余年的独裁统治告终。"},{"year": "1955", "name": "万隆会议", "desc": "1955年4月18日至24日，29个亚非国家和地区的代表在印尼万隆举行亚非会议，讨论民族独立、反殖民和世界和平等问题。会议通过《亚非会议最后公报》，提出和平相处、友好合作的十项原则，形成「万隆精神」。", "people": ["周恩来"]},{"year": "1961", "name": "不结盟运动兴起", "desc": "1961年9月1日至6日，第一次不结盟国家和政府首脑会议在南斯拉夫贝尔格莱德举行，25国代表出席，宣告不结盟运动正式形成。运动由铁托、纳赛尔、尼赫鲁等倡导，主张独立、自主、非集团。", "people": ["约瑟普·布罗兹·铁托"]},{"year": "1955", "name": "华沙条约组织成立", "desc": "1955年5月14日，苏联、波兰、捷克斯洛伐克、匈牙利、保加利亚、罗马尼亚、阿尔巴尼亚和民主德国8国在华沙签订《友好合作互助条约》，正式成立华沙条约组织，总部设于莫斯科，与北约形成两大军事集团对峙格局。"},{"year": "1935", "name": "共产国际第七次代表大会", "desc": "1935年7月25日至8月20日，共产国际在莫斯科召开第七次代表大会，也是其最后一次代表大会。65个共产党的代表出席，季米特洛夫作报告，大会确立建立反法西斯统一战线的方针。", "people": ["格奥尔基·季米特洛夫"]},{"year": "1946—1949", "name": "希腊内战", "desc": "1946年至1949年，希腊共产党领导的民主军与受英、美支持的希腊政府军爆发内战。民主军一度控制大部国土并于1947年建立临时政府，后因外部支援中断，1949年战败，内战结束。"},{"year": "1977", "name": "捷克斯洛伐克「七七宪章」", "desc": "1977年1月，241名捷克斯洛伐克各界人士签署并发表《七七宪章》宣言，要求政府遵守赫尔辛基人权文件、保障公民基本权利。哈维尔等为首届发言人，随后被捕入狱，该运动成为持不同政见力量的代表。"},{"year": "1960", "name": "沙佩维尔惨案", "desc": "1960年3月21日，南非泛非主义者大会在约翰内斯堡附近的沙佩维尔组织反对通行证法的游行示威，警察向人群开枪，造成约69人死亡、180余人受伤。事件引发全国抗议，南非当局宣布紧急状态并取缔非洲人国民大会等组织。"},{"year": "1976", "name": "索韦托起义", "desc": "1976年6月16日，约翰内斯堡西南郊黑人聚居区索韦托的学生举行示威，抗议当局强制黑人学校用南非荷兰语授课，遭警察开枪镇压。事件引发全国性抗议和暴动并持续一年多，成为南非反种族隔离斗争的重要转折。"}];
 var X=window.SITE_EXTRA||(window.SITE_EXTRA={});X.events=X.events||[];
 var has={};X.events.forEach(function(e){has[e.name]=1;});
 N.forEach(function(e){if(!has[e.name])X.events.push(e);});})();


/* ===== U7 增补：世界性事件的 背景 / 要点 / 影响 ===== */
(function(){var M={"朝鲜民主主义人民共和国成立": {"bg": "第二次世界大战结束后，朝鲜半岛以北纬三十八度线为界分别由美、苏军队进驻，南北双方各自筹备建政。", "points": ["1948 年 8 月南部先成立大韩民国", "9 月 9 日北方在平壤成立朝鲜民主主义人民共和国", "金日成出任内阁首相"], "impact": "半岛正式分裂为两个对立政权，成为此后朝鲜战争与长期对峙的起点。"}, "朝鲜战争爆发": {"bg": "南北分别建政后在三八线一带持续发生武装摩擦，冷战格局下双方均试图以武力实现统一。", "points": ["1950 年 6 月 25 日战争爆发", "联合国安理会决议介入，美国等组成「联合国军」", "同年 10 月中国人民志愿军入朝"], "impact": "战争持续三年，1953 年签订停战协定，半岛仍以三八线附近为界对峙。"}, "越南八月革命": {"bg": "第二次世界大战末期日本投降，印度支那的殖民与占领权力出现真空，越盟号召全国总起义。", "points": ["1945 年 8 月 19 日河内起义成功", "顺化、西贡相继解放，保大退位", "9 月 2 日胡志明宣读《独立宣言》"], "impact": "越南民主共和国成立，越南民族独立运动进入新阶段，随后即面临法国重返印度支那的战争。"}, "奠边府战役": {"bg": "第一次印度支那战争后期，法军试图在越南西北建立据点群以切断越盟通往老挝的通道。", "points": ["1954 年 3 月 13 日发起围攻", "激战约 55 昼夜", "5 月 7 日全歼守军 1.6 万余人"], "impact": "法国被迫在《日内瓦协议》上签字，第一次印度支那战争结束，越南暂时以北纬十七度线分治。"}, "越南南方解放与统一": {"bg": "《巴黎协定》后美军撤出，越南南方双方力量对比发生变化，北方决定以军事进攻实现统一。", "points": ["1975 年 3 月发动春季总进攻", "取得西原、顺化—岘港等战役胜利", "4 月 30 日攻占西贡，南越政权投降"], "impact": "1976 年越南南北统一，改国名为越南社会主义共和国。"}, "印尼「九三〇事件」": {"bg": "1960 年代印尼政治中陆军与印尼共产党影响均上升，总统苏加诺推行「纳沙贡」平衡各方。", "points": ["1965 年 9 月 30 日夜总统卫队军官翁东等人发动行动", "六名陆军将领被绑架并杀害", "苏哈托指挥陆军平定并指控印尼共产党为幕后主使"], "impact": "随后发生全国性反共清洗，印尼共产党被摧毁，苏加诺权威受损，苏哈托逐步掌权。"}, "古巴革命胜利": {"bg": "1950 年代古巴处于巴蒂斯塔独裁统治下，卡斯特罗等人 1953 年攻打蒙卡达兵营失败后转入游击斗争。", "points": ["1956 年「七二六运动」成员乘「格拉玛号」回国开展游击战", "1958 年底起义军发动反攻，攻占圣克拉拉", "1959 年 1 月 1 日巴蒂斯塔出逃，起义军进入哈瓦那"], "impact": "古巴革命取得胜利，此后推行土地改革与国有化，走上社会主义道路。"}, "古巴导弹危机": {"bg": "1962 年苏联为回应美国在土耳其部署导弹并在猪湾事件后保护古巴，决定在古巴部署中程核导弹。", "points": ["1962 年 10 月美国发现导弹基地并宣布海上封锁", "美苏一度濒临核战争", "经秘密谈判苏联撤走导弹"], "impact": "危机化解，美苏建立热线机制，成为冷战核对抗最危险的一次对峙。"}, "切·格瓦拉在玻利维亚遇害": {"bg": "1966 年格瓦拉离开古巴赴玻利维亚开展游击战，试图以「游击中心」方式推动南美革命。", "points": ["1967 年 10 月 8 日在尤罗峡谷战斗中被俘", "押至拉伊格拉村", "次日被处决，遗体被秘密掩埋"], "impact": "游击中心论受挫，格瓦拉成为国际左翼运动的重要象征。"}, "托洛茨基在墨西哥遇刺": {"bg": "托洛茨基被逐出苏联后辗转流亡，1937 年定居墨西哥，与斯大林一派持续论战。", "points": ["1940 年 8 月 20 日在墨西哥城郊住所遇袭", "被以化名接近的特工拉蒙·麦卡德用冰镐击伤头部", "次日伤重身亡"], "impact": "第四国际失去主要领导者，国际托派运动此后长期分裂。"}, "布拉格之春与苏联入侵捷克斯洛伐克": {"bg": "1960 年代捷克斯洛伐克经济困难、要求改革，杜布切克 1968 年初出任捷共第一书记。", "points": ["1968 年提出「带有人性面孔的社会主义」改革纲领", "8 月 20 日夜华约五国出兵占领", "改革被终止"], "impact": "「勃列日涅夫主义」（有限主权论）由此确立，东欧改革运动受到压制。"}, "波兰团结工会成立": {"bg": "1980 年波兰经济困难、物价上涨，工人罢工此起彼伏，格但斯克列宁造船厂成为中心。", "points": ["1980 年 8 月工人罢工并组成厂际罢工委员会", "瓦文萨为领导人", "9 月各地独立工会代表宣告成立团结工会"], "impact": "成为东欧首个非共产党控制的独立工会，深刻影响此后东欧政局。"}, "智利阿连德当选总统": {"bg": "1970 年智利左翼各党组成「人民团结」联盟推举阿连德参选，主张以宪政道路实现社会主义。", "points": ["1970 年 9 月阿连德以约 36% 得票率居首", "因未过半交由国会裁决", "10 月获国会确认，11 月就任总统"], "impact": "智利开始推行铜矿国有化、土地改革等政策，成为「和平过渡」路线的典型案例。"}, "智利军事政变": {"bg": "阿连德政府推行国有化并遭遇经济困难与政治对立，军方与反对派力量上升。", "points": ["1973 年 9 月 11 日三军与警察在圣地亚哥发动政变", "军队围攻并轰炸总统府拉莫内达宫", "阿连德身亡，人民团结政府被推翻"], "impact": "皮诺切特建立军政府并执政至 1990 年，智利的宪政社会主义道路中断。"}, "法国五月风暴": {"bg": "1960 年代法国高等教育规模扩大而体制僵化，学生运动兴起；工人亦要求提高待遇。", "points": ["1968 年 5 月巴黎大学生罢课示威并占领校园", "数百万工人罢工声援并占领工厂", "政府解散议会并举行大选"], "impact": "6 月运动逐渐消退，但推动了法国教育与社会文化领域的一系列改革。"}, "柏林墙倒塌": {"bg": "1980 年代末东欧剧变，东德大量民众外逃，要求放宽旅行限制的示威持续扩大。", "points": ["1989 年 11 月 9 日东德宣布开放边界", "大批市民涌向柏林墙各检查站", "边防军未加阻拦"], "impact": "柏林墙事实上被打开，1990 年两德统一，冷战格局加速终结。"}, "非洲独立年": {"bg": "第二次世界大战后殖民体系瓦解，亚非民族解放运动高涨，1957 年加纳率先独立。", "points": ["1960 年非洲 17 国获得独立", "多数为法属殖民地", "1955 年万隆会议推动亚非团结"], "impact": "非洲独立国家大批出现，改变了国际政治版图，此后非洲统一组织于 1963 年成立。"}, "阿尔及利亚独立战争": {"bg": "阿尔及利亚被法国视为本土一部分，战后民族意识高涨，民族解放阵线决心武装独立。", "points": ["1954 年 11 月在奥雷斯山区发动起义", "游击战与城市斗争相结合", "1962 年签订《埃维昂协议》"], "impact": "阿尔及利亚宣告独立，法国殖民帝国加速解体。"}, "埃及七月革命": {"bg": "战后埃及仍受英国影响，王室腐败、在巴勒斯坦战争中失利，军中「自由军官组织」密谋起事。", "points": ["1952 年 7 月 23 日在开罗发动起义", "7 月 26 日国王法鲁克一世退位流亡", "次年废除君主制成立共和国"], "impact": "纳赛尔随后掌权，推行苏伊士运河国有化，成为阿拉伯民族主义运动的核心人物。"}, "葡萄牙康乃馨革命": {"bg": "葡萄牙长期处于萨拉查—卡埃塔诺独裁统治下，殖民战争消耗巨大，军中下级军官酝酿政变。", "points": ["1974 年 4 月 25 日中下级军官发动政变", "以枪口插康乃馨为标志", "独裁政权被推翻"], "impact": "葡萄牙推行民主化并放弃殖民地，安哥拉、莫桑比克等相继独立。"}, "尼加拉瓜桑地诺革命": {"bg": "索摩查家族长期独裁并控制国民经济，桑地诺民族解放阵线自 1960 年代起开展游击斗争。", "points": ["1979 年发动全国攻势", "6 月成立民族复兴临时政府", "7 月 19 日进入首都马那瓜"], "impact": "索摩查家族统治告终，桑解阵执政并推行改革，中美洲局势随之变化。"}, "万隆会议": {"bg": "战后新独立的亚非国家要求摆脱殖民影响、加强团结，中国等倡议召开亚非会议。", "points": ["1955 年 4 月 18 日至 24 日在印尼万隆举行", "29 个亚非国家和地区代表出席", "通过《亚非会议最后公报》，提出十项原则"], "impact": "形成「万隆精神」，推动亚非团结与不结盟运动的兴起。"}, "不结盟运动兴起": {"bg": "冷战两大阵营对峙之下，新兴独立国家希望保持独立自主、不加入军事集团。", "points": ["1961 年 9 月第一次首脑会议在贝尔格莱德举行", "25 国代表出席", "由铁托、纳赛尔、尼赫鲁等倡导"], "impact": "不结盟运动正式形成，成为国际关系中的一支重要力量。"}, "华沙条约组织成立": {"bg": "1955 年西方国家吸收联邦德国加入北约，苏联与东欧国家随即筹组对应军事同盟。", "points": ["1955 年 5 月 14 日在华沙签订《友好合作互助条约》", "苏、波、捷、匈、保、罗、阿、民主德国 8 国参加", "总部设于莫斯科"], "impact": "欧洲形成北约与华约两大军事集团对峙的格局，冷战军事化程度加深。"}, "共产国际第七次代表大会": {"bg": "1930 年代法西斯势力扩张、战争威胁上升，共产国际需要调整策略以应对新形势。", "points": ["1935 年 7 月 25 日至 8 月 20 日在莫斯科举行", "65 个共产党的代表出席", "季米特洛夫作报告"], "impact": "确立建立反法西斯统一战线的方针，并决定一般不直接干涉各国党的内部事务。"}, "希腊内战": {"bg": "第二次世界大战后希腊左翼力量与王室、右翼势力对立，英国继而美国介入支持政府方。", "points": ["1946 年内战爆发", "民主军一度控制大部国土并建立临时政府", "1949 年民主军战败"], "impact": "希腊共产党被宣布非法，希腊加入西方阵营；此役被视为冷战在巴尔干的延伸。"}, "捷克斯洛伐克「七七宪章」": {"bg": "1968 年布拉格之春被镇压后，捷克斯洛伐克出现要求保障公民权利的持不同政见运动。", "points": ["1977 年 1 月 241 名各界人士签署《七七宪章》", "以赫尔辛基人权文件为依据", "哈维尔等为首届发言人"], "impact": "成为东欧反体制持不同政见力量的代表，为 1989 年政局变化准备了社会基础。"}, "沙佩维尔惨案": {"bg": "1959 年泛非主义者大会成立，发起反对通行证法的群众运动，与非洲人国民大会共同开展斗争。", "points": ["1960 年 3 月 21 日在沙佩维尔组织游行", "警察向人群开枪，约 69 人死亡", "当局宣布紧急状态并取缔相关组织"], "impact": "非洲人国民大会等被迫转向武装斗争，南非反种族隔离运动进入新阶段。"}, "索韦托起义": {"bg": "南非当局强制黑人学校以阿非利卡语（南非荷兰语）授课，引发学生和社区的强烈反对。", "points": ["1976 年 6 月 16 日索韦托学生举行示威", "遭警察开枪镇压", "抗议与暴动持续一年多"], "impact": "成为南非反种族隔离斗争的重要转折，大批青年此后参加解放运动。"}};
 ((window.SITE_EXTRA&&window.SITE_EXTRA.events)||[]).forEach(function(e){var m=M[e.name];if(!m)return;if(m.bg)e.bg=m.bg;if(m.points)e.points=m.points;if(m.impact)e.impact=m.impact;});})();


/* ===== U9 增补：世界性重大事件（著名/影响巨大，逐条联网核实）===== */
(function(){var N=[{"year": "1914", "name": "第一次世界大战爆发（萨拉热窝事件）", "desc": "1914年6月28日，奥匈帝国皇储斐迪南大公夫妇在波斯尼亚首府萨拉热窝被塞尔维亚青年普林西普刺杀。奥匈以最后通牒被拒为由，于7月28日对塞尔维亚宣战，欧洲列强因同盟与协约体系相继卷入，第一次世界大战爆发。", "bg": "巴尔干民族矛盾尖锐，奥匈与塞尔维亚对立，列强结盟对峙，被称为「欧洲火药桶」。", "points": ["1914年6月28日斐迪南大公夫妇遇刺", "奥匈7月28日对塞尔维亚宣战", "同盟国与协约国相继卷入战争"], "impact": "直接引发第一次世界大战，导致四大帝国崩溃，重塑欧洲与世界政治格局。"},{"year": "1919", "name": "《凡尔赛和约》签订", "desc": "1919年6月28日，第一次世界大战战胜国与德国在法国巴黎凡尔赛宫镜厅签署《凡尔赛和约》。和约规定德国承担战争罪责、割让领土、限制军备并支付赔款，同时包含国际联盟盟约。", "bg": "一战结束后战胜国召开巴黎和会，重新划分战后领土并安排国际秩序。", "points": ["1919年6月28日在凡尔赛宫镜厅签署", "德国割地、限制军备并承担赔款", "和约包含国际联盟盟约"], "impact": "确立凡尔赛体系，严苛的对德条约为日后冲突埋下隐患。"},{"year": "1929—1933", "name": "世界经济大危机（大萧条）", "desc": "1929年10月24日（「黑色星期四」）美国纽约华尔街股市暴跌，10月29日股市崩盘，引发席卷资本主义世界的经济大危机。危机持续至1933年，大批银行与企业倒闭，失业率激增。", "bg": "二十年代美国经济繁荣，股市投机盛行，供需矛盾与贫富分化不断加剧。", "points": ["1929年10月24日华尔街股市暴跌", "10月29日股市全面崩溃", "1929—1933年波及全球，工业产量骤降、失业激增"], "impact": "引发全球大萧条，催生贸易保护主义与法西斯势力，间接导致二战。"},{"year": "1939", "name": "第二次世界大战全面爆发（德国入侵波兰）", "desc": "1939年9月1日，德国军队以「白色方案」闪击波兰，凌晨德舰炮击但泽（今格但斯克）附近的西盘半岛。9月3日英、法对德宣战，第二次世界大战全面爆发。", "bg": "德国要求收回但泽及「波兰走廊」，英法对波兰提供安全保证。", "points": ["1939年9月1日德军闪击波兰", "德舰炮击西盘半岛，打响第一枪", "9月3日英、法对德宣战"], "impact": "第二次世界大战全面爆发，欧洲乃至全球陷入空前浩劫。"},{"year": "1941—1942", "name": "莫斯科保卫战", "desc": "1941年9月30日德军实施「台风」行动进攻莫斯科。苏军顽强防御，11月7日仍在红场举行阅兵，12月6日发起反攻，至1942年初将德军击退150—400公里，粉碎德军不可战胜的神话。", "bg": "1941年6月德国入侵苏联，德军企图攻占苏联首都以速胜。", "points": ["1941年9月30日德军发动「台风」行动", "1941年12月6日苏军开始反攻", "1942年初德军被迫西撤"], "impact": "粉碎德军闪电战，是德国开战以来首次重大失败。"},{"year": "1942—1943", "name": "斯大林格勒战役", "desc": "1942年7月德军进攻斯大林格勒（今伏尔加格勒）。11月19日苏军发动「天王星行动」合围德军第6集团军，1943年2月2日保卢斯率残部投降，历时约200天的战役结束。", "bg": "德军图夺高加索油田并控制伏尔加河交通线，斯大林格勒战略地位重要。", "points": ["1942年7月战役开始，市区巷战惨烈", "1942年11月19日「天王星行动」合围德军", "1943年2月2日德军投降"], "impact": "成为苏德战场及第二次世界大战的转折点。"},{"year": "1945", "name": "雅尔塔会议", "desc": "1945年2月4日至11日，苏、美、英三国首脑斯大林、罗斯福、丘吉尔在苏联克里米亚半岛雅尔塔举行会议，商讨处置德国、波兰问题、建立联合国及苏联对日作战等事项。", "bg": "二战后期德日败局已定，盟国亟需协调战后安排。", "points": ["1945年2月4—11日举行", "决定分区占领德国、建立联合国", "秘密签订《雅尔塔协定》"], "impact": "确立雅尔塔体系，奠定战后世界格局，同时损害中国等国权益。"},{"year": "1945", "name": "联合国成立", "desc": "1945年4月25日至6月26日，50国代表在美国旧金山召开联合国制宪会议并通过《联合国宪章》。10月24日宪章生效，联合国正式成立，中、法、苏、英、美为安理会常任理事国。", "bg": "二战中反法西斯同盟酝酿建立维护世界和平的普遍性国际组织。", "points": ["1945年4—6月举行旧金山制宪会议", "6月26日通过并签署《联合国宪章》", "10月24日联合国正式成立"], "impact": "成为最具普遍性的国际组织，奠定战后国际秩序的基石。"},{"year": "1945", "name": "广岛原子弹爆炸", "desc": "1945年8月6日，美军B-29轰炸机在广岛投下代号「小男孩」的原子弹，炸弹在距地面约580米空中爆炸。这是人类首次将核武器用于实战，城市化为废墟，伤亡惨重。", "bg": "日本拒绝接受《波茨坦公告》，美国决定动用原子弹。", "points": ["1945年8月6日投下「小男孩」", "人类首次实战使用核武器", "8月9日长崎再遭原子弹轰炸"], "impact": "加速日本投降与二战结束，开启核武器时代。"},{"year": "1947", "name": "印度独立", "desc": "1947年6月英国公布「蒙巴顿方案」，实行印巴分治。8月15日印度宣告独立，尼赫鲁出任总理，结束英国约190年的殖民统治。此前甘地长期领导非暴力不合作运动。", "bg": "二战后印度民族独立运动高涨，国大党与穆斯林联盟矛盾激化。", "points": ["1947年6月公布「蒙巴顿方案」", "1947年8月15日印度宣布独立", "印巴分治引发大规模教派冲突"], "impact": "加速英国殖民体系瓦解，开启南亚民族独立的新格局。"},{"year": "1969", "name": "阿波罗11号登月", "desc": "1969年7月16日，美国「土星5号」火箭搭载阿波罗11号飞船从佛罗里达州肯尼迪航天中心39A发射台升空。7月20日登月舱「鹰」号在月球静海着陆，阿姆斯特朗成为首位踏上月表的人类。", "bg": "冷战背景下美苏太空竞赛，肯尼迪提出十年内实现载人登月。", "points": ["1969年7月16日于肯尼迪航天中心发射", "7月20日阿姆斯特朗、奥尔德林登月", "7月24日返回地球"], "impact": "人类首次登月成功，成为世界航天史上的里程碑。"},{"year": "1979", "name": "伊朗伊斯兰革命", "desc": "1978年伊朗爆发反国王的群众运动，1979年1月16日国王巴列维流亡国外，2月1日霍梅尼回国，4月1日宣布成立伊朗伊斯兰共和国，建立政教合一的制度。", "bg": "巴列维推行西化改革，贫富分化与宗教矛盾激化，民怨沸腾。", "points": ["1978年反国王运动席卷全国", "1979年1月巴列维流亡国外", "1979年4月1日成立伊斯兰共和国"], "impact": "改变中东力量格局，冲击美国中东政策，推动伊斯兰复兴运动。"},{"year": "1979", "name": "苏联入侵阿富汗", "desc": "1979年12月24—27日，苏联军队大举空运并进入阿富汗，12月27日晚突袭喀布尔、攻占阿明官邸并击毙阿明，扶植卡尔迈勒上台，对阿富汗实行军事占领，战争持续至1989年苏军撤离。", "bg": "阿富汗政局动荡，苏联为确保亲苏政权、争夺战略要地而出兵。", "points": ["1979年12月苏军大举入侵阿富汗", "12月27日攻占喀布尔、击毙阿明", "1989年苏军全部撤离"], "impact": "苏联深陷战争泥潭，削弱国力，推动其最终解体。"},{"year": "1989", "name": "天鹅绒革命（捷克斯洛伐克）", "desc": "1989年11月17日布拉格学生游行遭镇压，引发连日大规模和平示威。11月27日全国总罢工，捷共放弃权力，12月29日哈维尔当选总统；因全程无暴力而得名「天鹅绒革命」。", "bg": "东欧剧变与柏林墙倒塌刺激捷克斯洛伐克对变革的期望。", "points": ["1989年11月17日布拉格游行为起点", "11月27日全国总罢工", "12月哈维尔当选总统"], "impact": "和平结束捷克斯洛伐克共产党统治，推动东欧剧变进程。"},{"year": "1990—1994", "name": "曼德拉获释与南非废除种族隔离", "desc": "1990年2月11日，被囚禁27年的曼德拉从开普敦附近的维克托·韦斯特监狱获释。此后南非逐步废除种族隔离制度，1994年4月举行首次不分种族的全民大选，曼德拉当选首位黑人总统。", "bg": "南非长期实行种族隔离制度，国际社会施压，德克勒克推行政治改革。", "points": ["1990年2月11日曼德拉获释", "1991年南非废除种族隔离制度", "1994年首次全民大选，曼德拉当选总统"], "impact": "结束种族隔离，开启南非民主与种族和解进程。"},{"year": "1992（1993年生效）", "name": "《马斯特里赫特条约》与欧洲联盟成立", "desc": "1992年2月7日，欧洲共同体12国在荷兰马斯特里赫特正式签署《马斯特里赫特条约》（即《欧洲联盟条约》）。条约于1993年11月1日生效，欧共体更名为欧洲联盟，为欧元与欧洲一体化奠定基础。", "bg": "冷战结束前后，欧洲一体化深化，谋求经济货币联盟与政治联盟。", "points": ["1992年2月7日正式签署《马约》", "1993年11月1日生效，欧盟成立", "为单一货币欧元奠定基础"], "impact": "标志欧洲联盟的诞生，是欧洲一体化的重要里程碑。"},{"year": "1990", "name": "两德统一", "desc": "1989年11月9日柏林墙开放。1990年两德与美、英、法、苏达成「2+4」协议，8月签署统一条约，10月3日民主德国并入联邦德国，分裂40余年的德国重新统一。", "bg": "东欧剧变与柏林墙倒塌，东德政局动荡，统一呼声高涨。", "points": ["1989年11月9日柏林墙开放", "1990年8月签署两德统一条约", "1990年10月3日两德正式统一"], "impact": "标志冷战与欧洲分裂格局的转折，柏林重新成为德国首都。"}];
 var X=window.SITE_EXTRA||(window.SITE_EXTRA={});X.events=X.events||[];
 var has={};X.events.forEach(function(e){has[e.name]=1;});
 N.forEach(function(e){if(!has[e.name])X.events.push(e);});})();
